<script setup>
import { ref } from 'vue'
import { Search, Plug, CalendarDays, FileText, Mail, MessageCircle, Check, Plus, ArrowUpRight, MoreHorizontal } from 'lucide-vue-next'
const query=ref(''), apps=ref([{name:'Google Calendar',desc:'Sync events and manage your schedule.',category:'Productivity',icon:CalendarDays,color:'blue',connected:true},{name:'Notion',desc:'Search and summarize your workspace.',category:'Productivity',icon:FileText,color:'gray',connected:true},{name:'Gmail',desc:'Summarize email and draft replies.',category:'Communication',icon:Mail,color:'red',connected:false},{name:'Telegram',desc:'Receive updates and quick notifications.',category:'Communication',icon:MessageCircle,color:'cyan',connected:false}])
const filtered=()=>apps.value.filter(a=>a.name.toLowerCase().includes(query.value.toLowerCase()))
function toggle(app){app.connected=!app.connected}
</script>
<template><div class="page"><header class="page-header"><div><div class="eyebrow">MAKE DAYWAVE YOURS</div><h1>Integrations</h1><p class="page-subtitle">Connect the tools you use every day. DayWave works better with context.</p></div></header><div class="integration-toolbar"><div class="search-field"><Search :size="17"/><input v-model="query" placeholder="Search integrations"></div><button class="secondary-btn"><Plug :size="16"/> Browse catalog</button></div><div class="section-title"><h2>Connected</h2><span class="count-badge">{{apps.filter(a=>a.connected).length}}</span></div><div class="integration-grid"><article v-for="app in filtered().filter(a=>a.connected)" :key="app.name" class="integration-card"><div class="integration-top"><div class="integration-logo" :class="app.color"><component :is="app.icon" :size="21"/></div><button class="tiny-icon"><MoreHorizontal :size="17"/></button></div><h3>{{app.name}}</h3><p>{{app.desc}}</p><div class="integration-footer"><span class="connected-label"><Check :size="14"/> Connected</span><button class="text-btn" @click="toggle(app)">Manage</button></div></article></div><div class="section-title available-title"><h2>Available integrations</h2><span class="count-badge">{{apps.filter(a=>!a.connected).length}}</span></div><div class="integration-grid"><article v-for="app in filtered().filter(a=>!a.connected)" :key="app.name" class="integration-card"><div class="integration-top"><div class="integration-logo" :class="app.color"><component :is="app.icon" :size="21"/></div><span class="category-tag">{{app.category}}</span></div><h3>{{app.name}}</h3><p>{{app.desc}}</p><div class="integration-footer"><span class="available-label">Not connected</span><button class="connect-btn" @click="toggle(app)"><Plus :size="14"/> Connect</button></div></article></div></div></template>